```php
// 导入jwt库
require_once 'path/to/jwt/libraries/jwt.php';
// 创建一个JWT对象，并设置要传递的claims（即数据）
$claims = [
  'user_id' => 123,
  'role' => 'admin',
];
// 序列化的数据
$data = JwtUtils::serialize($claims);
// 获取一个签名密钥
$signingKey = 'YOUR_SECRET_KEY';
// 设置过期时间，单位为秒
$interval = 3600;
// 额内设置签名密钥和过期时间
$payload = JwtUtils::setClaimSign($interval, $signingKey, $data);
// 将设置后的数据附加到原始数据对象中，并生成JWT
$jwt = JwtUtils::createToken($jwt, $payload);
// 将JWT对象序列化并输出
echo "JWT: " . json_encode($jwt);
```
接下来，我们可以通过以下方式验证JWT的有效性并提取数据：
