```
以上代码中，`JwtUtils::createToken()`方法用于生成JWT，其中传入的jwt对象包含所有设置的数据，而`$payload`对象则包含了所要传递的数据。生成后的JWT对象中包含了所有数据。
```php
// 定义一个JWT验证方法
function validateJWT($jwt, $signing_key, $interval = null) {
  // 声明一个JWT验证对象
  $decoded_header = JwtUtils::parseHeader($jwt);
  $decoded_body = JwtUtils::parsePayload($jwt, $signing_key);
  // 将数据封装成一个数据对象
  $data = JwtUtils::serialize([JwtUtils::serializeBody($decoded_body), $decoded_header]);
  // 解码JWT以验证其有效
  JwtUtils::decodeToken($jwt);
  // 检查JWT的过期时间
  if (!is_null($interval) && ($decoded_header['exp'] > time())) {
    return ['success' => false, 'message' => 'JWT已经过期'];
  }
  // 检查JWT的签名是否有效
  if (JwtUtils::verifyToken($jwt, $signing_key)) {
    return ['success' => true, 'data' => $data];
  } else {
    return ['success' => false, 'message' => 'Invalid signature'];
  }
}

