from sympy import symbols, Eq, solve

# Define the variables
n, m = symbols('n m')

# Define the equations
eq1 = Eq(n + m, 10)
eq2 = Eq(n + 2*m, 18)

# Solve the system of equations
solution = solve((eq1, eq2), (n, m))
n_value = solution[n]
m_value = solution[m]

# Calculate the current mean
current_mean = m_value
print(current_mean)
